import json
with open("/root/.nanobot/mempalace/palace/palace.json") as f:
    d = json.load(f)
flat = []
for wing, rooms in d.items():
    for room_key, halls in rooms.items():
        for hall_key, docs in halls.items():
            flat.append((wing, room_key, hall_key, len(docs)))
print(f"Total wings: {len(d)}\n")
by_wing = {}
for w,r,h,cnt in flat:
    by_wing.setdefault(w,[]).append(cnt)
for w,lst in sorted(by_wing.items()):
    print(f"  {w}: {sum(lst)} docs ({len(lst)} rooms)")
print(f"\nGrand total: {sum(sum(v) for v in by_wing.values())} documents")
PYEOF
